    ok("!! SIZES goes red for a short arm in either condition; IDS ALIGNED, SCORES INSIDE (0, 1) and POWERS go red alone for a shifted key, a score of 1, a score of 0, a power below 200 W and a NaN thrust; exactly 200 W is clean", (() => { const a = mkAu(); a.dark.w02_26014 = a.dark.w02_26014.slice(1); const b = mkAu(); b.lit.s02_26011 = b.lit.s02_26011.slice(1); const c = mkAu(); c.lit.q02[2].key = "x"; const d = mkAu(); d.dark.s02_26011[0].score = 1; const e = mkAu(); e.dark.s02_26011[0].score = 0; const f = mkAu(); f.dark.w02_26011[0].watts = 100; const g = mkAu(); g.lit.w02_26011[0].thrust = NaN; const h = mkAu(); h.dark.w02_26011[0].watts = 200; return has(a, "SIZES") && has(b, "SIZES") && only(c, "IDS ALIGNED") && only(d, "SCORES INSIDE") && only(e, "SCORES INSIDE") && only(f, "POWERS") && only(g, "POWERS") && reds(h).length === 0; })());
    ok("!! EVENT REACHES THE FLIGHT goes red alone when the autopilot's dark and lit scores are identical (and stays clean when ONE id differs); ZERO LAW goes red when law0 differs by 1e-5 in score, power or thrust", (() => { const a = mkAu(); a.lit.autopilot = a.dark.autopilot.map((r) => ({ ...r })); a.dark.law0 = a.dark.autopilot.map((r) => ({ ...r })); a.lit.law0 = a.lit.autopilot.map((r) => ({ ...r })); const one = mkAu(); one.lit.autopilot = one.dark.autopilot.map((r, i) => ({ ...r, score: i === 7 ? r.score + 0.01 : r.score })); one.dark.law0 = one.dark.autopilot.map((r) => ({ ...r })); one.lit.law0 = one.lit.autopilot.map((r) => ({ ...r })); const mk = (k) => { const b = mkAu(); b.dark.law0[4][k] += 1e-5; return b; }; return only(a, "EVENT REACHES") && reds(one).length === 0 && only(mk("score"), "ZERO LAW") && only(mk("watts"), "ZERO LAW") && only(mk("thrust"), "ZERO LAW"); })());
