    ok("!! 4 SEARCHES goes red for three searches, a seed twice, a row of another group, a missing checkpoint, a checkpoint at the wrong iteration (2701), a short weight vector, a NaN weight, a NaN held-out value, three flown networks, flown networks swapped, and a bad wip", (() => { const a = mkAu(); a.search.pop(); const b = mkAu(); b.search[1].seed = b.search[0].seed; const c = mkAu(); c.search[0].group = "S02"; const d = mkAu(); d.search[3].checkpoints.pop(); const e = mkAu(); e.search[2].checkpoints[1].iter = 2701; const f = mkAu(); f.search[1].checkpoints[2].weights = w963(0).slice(1); const g = mkAu(); g.search[2].checkpoints[3].weights = w963(NaN); const h = mkAu(); h.search[3].checkpoints[0].heldScore = NaN; const i = mkAu(); i.fresh.nets.pop(); const j = mkAu(); j.wip = [1]; const k = mkAu(); k.fresh.nets = [k.fresh.nets[1], k.fresh.nets[0], k.fresh.nets[2], k.fresh.nets[3]]; return [a, b, c, d, e, f, g, h, i, j, k].every((x) => has(x, "4 SEARCHES")); })());
    ok("!! ID SETS goes red alone for an audit range touching the old train ids or the held-out ids at one id, starting on 37399 (H36's last id), and is clean from 37400; the text names 26000-26023 and 30000-30047 and 37399", [{ from: 26023, to: 26060 }, { from: 29990, to: 30000 }, { from: 30047, to: 30060 }, { from: 26060, to: 26100 }, { from: 37399, to: 37438 }].every((rg) => has(mkAu({}, { range: rg }), "ID SETS")) && !has(mkAu({}, { range: { from: 37400, to: 37439 } }), "ID SETS") && (() => { const t = all(mkAu()).find((r) => r.name.startsWith("ID SETS")).text; return /26000-26023 and 30000-30047/.test(t) && /37399/.test(t); })());
