    ok("!! THE FIRST PARENT goes red alone for one search whose start value is off in the last digit, for a missing start value, for a larger-start value that differs from wip's by the last digit or is missing, and for a start value that differs from H32's stored one by the last digit or is missing; the text says the 72 train ids", (() => { const a = mkAu(); a.search[2].startTrain += 1e-12; const c = mkAu(); c.startVal = null; const d = mkAu(); d.startVal32 += 1e-12; const e = mkAu(); e.startVal32 = null; const f = mkAu(); f.startValWide += 1e-12; const g = mkAu(); g.startValWide = null; return [a, c, d, e, f, g].every((x) => only(x, "THE FIRST PARENT")) && /72 train ids/.test(all(mkAu()).find((r) => r.name.startsWith("THE FIRST")).text); })());
    ok("!! THE START IS FUNCTION-PRESERVING goes red alone for a difference of 1e-9 or more, a nonzero weight that reads a new neuron, a count of drawn inputs that does not match, a wrong dimension, a probe of another size and a missing probe; clean on the real probe", (() => { const mk = (f) => { const a = mkAu(); f(a.preserve); return a; }; const cases = [mk((p) => { p.maxDiff = 1e-9; }), mk((p) => { p.maxDiff = NaN; }), mk((p) => { p.readZero = false; }), mk((p) => { p.fed -= 1; }), mk((p) => { p.dimension -= 1; }), mk((p) => { p.n = 49; }), mkAu({}, { preserve: null })]; return cases.every((x) => only(x, "THE START IS FUNCTION")) && reds(mkAu()).length === 0 && mkAu().preserve.drawn > 0; })());
    ok("!! THE START FLIES AS NETWORK-WIP goes red alone for a larger-start flight that differs in score, lost flag, power, thrust or key at one id by the last digit, in either condition; for fewer than 5 ids, a flight at another number of seconds and a missing record; clean when identical", (() => { const mk = (f) => { const a = mkAu(); f(a.flyStart); return a; }; const cases = [mk((p) => { p.wide.dark[2].score += 1e-12; }), mk((p) => { p.wide.lit[4].watts += 1e-9; }), mk((p) => { p.wide.dark[0].thrust += 1e-12; }), mk((p) => { p.wide.lit[1].bad = true; }), mk((p) => { p.wide.dark[3].key = "x"; }), mk((p) => { p.wide.dark.pop(); p.wip.dark.pop(); }), mk((p) => { p.seconds = 20; }), mkAu({}, { flyStart: null })]; return cases.every((x) => only(x, "THE START FLIES")) && reds(mkAu()).length === 0; })());
    ok("!! THE CHAMPION row stays clean on a consistent set and goes red with the searches when a held-out value is NaN", reds(mkAu()).length === 0 && (() => { const x = mkAu(); x.search[0].checkpoints[3].heldScore = NaN; return has(x, "4 SEARCHES") && has(x, "THE CHAMPION"); })());
    ok("!! THE FOUR S02 ARMS goes red when a network is not its seed's 1800 weights in H32's result (swapped, last digit, short), when s02_26011 is not H32's champion (another seed's held-out value raised above), when there are three networks and when H32's search is missing", (() => { const a = mkAu(); a.s32.nets = [a.s32.nets[1], a.s32.nets[0], a.s32.nets[2], a.s32.nets[3]]; const b = mkAu(); b.s32.nets[2] = b.s32.nets[2].slice(); b.s32.nets[2][5] += 1e-12; const c = mkAu(); c.s32.nets[3] = c.s32.nets[3].slice(1); const d = mkAu(); d.h32.search.find((r) => r.seed === 26013).checkpoints[3].heldScore = 0.9; const e = mkAu(); e.s32.nets.pop(); const f = mkAu(); f.h32 = null; return [a, b, c, d, e, f].every((x) => has(x, "THE FOUR S02 ARMS")); })());
    ok("!! C02, WIP AND Q02 go red for a c02 changed in the last digit, a wip changed by one weight, a wip changed by 5e-8 in one weight, a q02 that is not H27's champion law and a missing H27 original", (() => { const a = mkAu(); a.c02[0] += 1e-9; const f = mkAu(); f.wip = WIP.slice(); f.wip[7] += 1e-6; const f2 = mkAu(); f2.wip = WIP.slice(); f2.wip[7] += 5e-8; const b = mkAu(); b.h27 = { laws: [[9, 9, 9, 9]] }; const g = mkAu(); g.original = null; return [a, f, f2, b, g].every((x) => has(x, "C02, WIP AND Q02")); })());
    ok("!! THE SEEDS row goes red when H32's seeds are not all in its stored search (a list that was not read or lacks 26014), when the list is missing, and when a searched seed is a stranger; clean otherwise", only(mkAu({}, { earlier: [26011, 26012, 26013] }), "THE SEEDS") && only(mkAu({}, { earlier: null }), "THE SEEDS") && only(mkAu({}, { earlier: [] }), "THE SEEDS") && reds(mkAu({}, { earlier: [26014, 26013, 26012, 26011] })).length === 0 && (() => { const x = mkAu(); x.search[0].seed = 26031; return has(x, "THE SEEDS") && has(x, "4 SEARCHES"); })());
