    ok("!! the REPORTED line gives the use of the new neurons for each larger network (L1 over the new-neuron weights and the old ones, and how many of the 785 weights that read a new neuron are nonzero), the audit means of all eight networks in rank order (best first) and the unpenalised gain; the LOST line names every lost run by arm, condition and id and not the autopilot's", (() => { const x = mkAu({ w02_26012: 0.05, s02_26011: -0.03 }); x.dark.w02_26013[7].bad = true; x.lit.s02_26011[3].bad = true; x.dark.autopilot[5].bad = true; const b = X.bottomLines(x); return /use of the new neurons w02_26011 new-neuron weights L1 [\d.]+, old weights L1 [\d.]+, 785 of 785 new-neuron output weights nonzero; w02_26012 new-neuron/.test(b[11]) && /audit means in rank order \(penalised priced score at 0\.02\) w02_26012 [\d.]+, /.test(b[11]) && b[11].split(/rank order[^;]*?\) /)[1].split(";")[0].split(", ").length === 8 && /the lost runs: s02_26011 lit k3, w02_26013 dark k7$/.test(b[6]) && /LOST \(runs lost of 400\): law0 0, c02 0, q02 0, s02_26011 1, s02_26012 0, s02_26013 0, s02_26014 0, w02_26011 0, w02_26012 0, w02_26013 1, w02_26014 0;/.test(b[6]); })());
    ok("!! the check texts carry the registered numbers (the checkpoints 900 to 1800 of the larger weights, 68 neurons and the generator seeded 4243, the function-preserving start to 1e-9 on 50 vectors, the 5 ids flown at 160 s, the 72 train ids, the seeds 26011-26014, H36's last id 37399, H32's 12-iteration proof killed after 6)", (() => { const c = X.checksOf(mkAu()), t = (n) => c.find((r) => r.name.startsWith(n)).text; return /checkpoints at 900, 1200, 1500 and 1800 of 2571 finite weights/.test(t("4 SEARCHES")) && /1800-iteration weights/.test(t("4 SEARCHES")) && /68 neurons \(the fly's 34, then 34 new\), the fly's 313 edges first, then 962 new edges, each pair touching a new neuron an edge below 313\/1122 by the generator seeded 4243/.test(t("THE TOPOLOGY")) && /agrees with network-Wip's to 1e-9 on 50 random feature vectors, every weight that reads a new neuron is zero, and every weight that feeds one is the registered draw \(789 of them\)/.test(t("THE START IS FUNCTION")) && /registerPilotKind\) scores exactly as network-Wip does, dark and lit, in key, score, lost flag, power and thrust, on 5 ids at 160 s/.test(t("THE START FLIES")) && /72 train ids at 0\.02/.test(t("THE FIRST")) && /are 26011-26014/.test(t("THE SEEDS")) && /after H36's audit \(37399\)/.test(t("ID SETS")) && /12 iterations, killed after iteration 6, resumed from the state at 4/.test(t("THE SEARCH IS")) && /s02_26011 to s02_26014 are the weights at 1800/.test(t("THE FOUR S02")); })());
    ok("!! the tables list the right arms: the means list all 12 (autopilot first), the per-arm gains and the LOST, EXTRA POWER and PRICED GAIN lists leave the autopilot out, law0 prints a +0.0000 gain with its sign, and the report header says 0.02", (() => { const R = X.report(mkAu()), at = R.findIndex((l) => l.startsWith("per arm:")), bl2 = X.bottomLines(mkAu()); return R.slice(R.findIndex((l) => l.startsWith("means")) + 1, at).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.join() && R[at + 1].startsWith("  law0       +0.0000 / +0.0000") && R.slice(at + 1, at + 12).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.slice(1).join() && bl2[6].startsWith("LOST (runs lost of 400): law0 0, c02 0") && bl2[7].startsWith("EXTRA POWER (mean of dark and lit extra kW): c02 ") && bl2[8].includes("PENALISED PRICED GAIN (at 0.005 / 0.02 / 0.04): c02 ") && bl2[5].startsWith("AUDIT (dark / lit mean score, dark mean power, mean dark thrust): autopilot ") && /penalised priced score at 0\.02/.test(R[0]) && R.some((l) => l === "per arm: dark / lit gain over the autopilot, extra power (kW, dark / lit), penalised priced gain at 0.005 / 0.02 / 0.04:") && R.some((l) => l === "means (dark score / lit score; dark mean power kW; lit mean power kW; lost runs of 400):") && R.some((l) => l.startsWith("  autopilot  0.")); })());
