    ok("!! the wide policy is named for what it is ('the Giant Fiber Circuit plus 34 new neurons'); netObj accepts a price of 0 and refuses a negative one; the three flight defaults in the library (netObj, flyStartOf, startValWide) and the others are H28's flyPen, read from the source because no wide candidate crashes the flight", X.WIDE.name === "the Giant Fiber Circuit plus 34 new neurons" && (() => { const fake = (arm, range) => Array.from({ length: range.to - range.from + 1 }, () => ({ key: "k", score: 0.7, bad: false, watts: 5000, thrust: 0 })); return near(X.netObj(START, [{ from: 1, to: 1 }], 0, 5, fake), 0.7) && /the price must be a number of 0 or more/.test(thr(() => X.netObj(START, [{ from: 1, to: 1 }], -0.01, 5, fake))); })() && (code.match(/flyFn = flyPen/g) || []).length === 6 && !/flyFn = H15\.fly/.test(code));
    ok("!! champion names the group and seeds for a non-list and for a stranger seed in place of a real one (the 'needs one search' message, not a TypeError)", (() => { const ra = [26011, 26012, 26013, 26014].map((s) => ({ seed: s, group: "W02", checkpoints: X.CHECKPOINTS.map((iter) => ({ iter, weights: [], trainScore: 0, heldScore: 0.5, accepted: 0 })) })); return /needs one search for each of the seeds/.test(thr(() => X.champion(null, 900))) && /needs one search for each of the seeds/.test(thr(() => X.champion([...ra.slice(1), { ...ra[0], seed: 26099 }], 900))); })());
