    ok("!! champion refuses an iteration that is not a checkpoint (600, 0, 1800.5) with the 'needs one search' message even when every row is whole, and a row set with an extra checkpoint at 600 does not make 600 legal", (() => { const ra = [26011, 26012, 26013, 26014].map((q) => ({ seed: q, group: "W02", checkpoints: [600, ...X.CHECKPOINTS].map((iter) => ({ iter, weights: [], trainScore: 0, heldScore: 0.5, accepted: 0 })) })); return [600, 0, 1800.5].every((it) => /needs one search for each of the seeds/.test(thr(() => X.champion(ra, it)))) && X.champion(ra, 900).seed === 26011; })());
